INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-01-1', 'corps-sante-ch01', 'Besoins des cellules', 'les cellules ont besoin d’oxygène pour décomposer les molécules alimentaires, produisant ainsi de l’énergie (respiration cellulaire).', 'corps-humain-sante', 4, 1, 'Besoins des cellules : les cellules ont besoin d’oxygène pour décomposer les molécules alimentaires, produisant ainsi de l’énergie (respiration cellulaire).', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-02-1', 'corps-sante-ch01', 'Adaptations respiratoires à l’effort', 'augmentation de la fréquence respiratoire et de l’amplitude des mouvements respiratoires pour capter plus d’O₂.', 'corps-humain-sante', 4, 2, 'Adaptations respiratoires à l’effort : augmentation de la fréquence respiratoire et de l’amplitude des mouvements respiratoires pour capter plus d’O₂.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-03-1', 'corps-sante-ch01', 'Poumons et alvéoles', 'grande surface d’échange favorisant le passage de l’O₂ dans le sang et l’élimination du CO₂.', 'corps-humain-sante', 4, 3, 'Poumons et alvéoles : grande surface d’échange favorisant le passage de l’O₂ dans le sang et l’élimination du CO₂.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-04-1', 'corps-sante-ch01', 'Adaptations cardiovasculaires', 'augmentation de la fréquence cardiaque et du débit cardiaque pour acheminer plus rapidement le sang oxygéné vers les muscles.', 'corps-humain-sante', 4, 4, 'Adaptations cardiovasculaires : augmentation de la fréquence cardiaque et du débit cardiaque pour acheminer plus rapidement le sang oxygéné vers les muscles.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-05-1', 'corps-sante-ch01', 'Réseau de capillaires', 'densité élevée autour des organes actifs, facilitant les échanges entre le sang et les cellules.', 'corps-humain-sante', 4, 5, 'Réseau de capillaires : densité élevée autour des organes actifs, facilitant les échanges entre le sang et les cellules.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-06-1', 'corps-sante-ch01', 'Adaptations à long terme', 'entraînement physique → cœur plus efficace, meilleure capacité respiratoire, meilleure oxygénation des tissus.', 'corps-humain-sante', 4, 6, 'Adaptations à long terme : entraînement physique → cœur plus efficace, meilleure capacité respiratoire, meilleure oxygénation des tissus.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p04-07-1', 'corps-sante-ch01', 'Lien respiration–circulation', 'la respiration oxygène le sang, la circulation distribue l’O₂ et récupère le CO₂', 'corps-humain-sante', 4, 7, 'Lien respiration–circulation : la respiration oxygène le sang, la circulation distribue l’O₂ et récupère le CO₂', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-01-1', 'corps-sante-ch02', 'Effort physique', 'augmente les besoins des muscles en dioxygène et en énergie.', 'corps-humain-sante', 6, 1, 'Effort physique : augmente les besoins des muscles en dioxygène et en énergie.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-02-1', 'corps-sante-ch02', 'Récupération', 'phase indispensable après l’effort permettant l’élimination des déchets (CO₂), la reconstitution des réserves énergétiques et la réparation des tissus.', 'corps-humain-sante', 6, 2, 'Récupération : phase indispensable après l’effort permettant l’élimination des déchets (CO₂), la reconstitution des réserves énergétiques et la réparation des tissus.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-03-1', 'corps-sante-ch02', 'Dette en dioxygène', 'après l’effort, l’organisme consomme davantage d’O₂ pour revenir à l’équilibre.', 'corps-humain-sante', 6, 3, 'Dette en dioxygène : après l’effort, l’organisme consomme davantage d’O₂ pour revenir à l’équilibre.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-04-1', 'corps-sante-ch02', 'Rôle de la circulation', 'le sang élimine les déchets et apporte nutriments et dioxygène nécessaires à la récupération.', 'corps-humain-sante', 6, 4, 'Rôle de la circulation : le sang élimine les déchets et apporte nutriments et dioxygène nécessaires à la récupération.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-05-1', 'corps-sante-ch02', 'Entraînement régulier', 'provoque des adaptations durables (cœur plus efficace, muscles mieux oxygénés, meilleure endurance).', 'corps-humain-sante', 6, 5, 'Entraînement régulier : provoque des adaptations durables (cœur plus efficace, muscles mieux oxygénés, meilleure endurance).', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-06-1', 'corps-sante-ch02', 'Adaptations cardiovasculaires', 'baisse de la fréquence cardiaque au repos, augmentation du débit cardiaque maximal.', 'corps-humain-sante', 6, 6, 'Adaptations cardiovasculaires : baisse de la fréquence cardiaque au repos, augmentation du débit cardiaque maximal.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p06-07-1', 'corps-sante-ch02', 'Adaptations respiratoires', 'augmentation de la capacité ventilatoire et amélioration des échanges gazeux.', 'corps-humain-sante', 6, 7, 'Adaptations respiratoires : augmentation de la capacité ventilatoire et amélioration des échanges gazeux.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p08-01-1', 'corps-sante-ch03', 'Digestion', 'ensemble des transformations mécaniques et chimiques des aliments dans le tube digestif.', 'corps-humain-sante', 8, 1, 'Digestion : ensemble des transformations mécaniques et chimiques des aliments dans le tube digestif.', NULL, 11);
