INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p08-06-1', 'corps-sante-ch03', 'Villosités intestinales', 'replis de la paroi intestinale augmentant fortement la surface d’absorption.', 'corps-humain-sante', 8, 6, 'Villosités intestinales : replis de la paroi intestinale augmentant fortement la surface d’absorption.', NULL, 61);
