INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p10-01-1', 'corps-sante-ch04', 'Besoins énergétiques', 'l’organisme a besoin d’énergie pour le fonctionnement des organes, l’activité physique, la croissance et le maintien de la température corporelle.', 'corps-humain-sante', 10, 1, 'Besoins énergétiques : l’organisme a besoin d’énergie pour le fonctionnement des organes, l’activité physique, la croissance et le maintien de la température corporelle.', NULL, 11);
