INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p14-06-1', 'corps-sante-ch06', 'Message nerveux', 'information transmise sous forme électrique le long des neurones.', 'corps-humain-sante', 14, 6, 'Message nerveux : information transmise sous forme électrique le long des neurones.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p14-07-1', 'corps-sante-ch06', 'Comparaison', 'le réflexe est plus rapide que la commande volontaire, mais moins adaptable.', 'corps-humain-sante', 14, 7, 'Comparaison : le réflexe est plus rapide que la commande volontaire, mais moins adaptable.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-01-1', 'corps-sante-ch07', 'Puberté', 'période de transformations physiques, physiologiques et hormonales conduisant à la maturité sexuelle.', 'corps-humain-sante', 17, 1, 'Puberté : période de transformations physiques, physiologiques et hormonales conduisant à la maturité sexuelle.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-02-1', 'corps-sante-ch07', 'Rôle des hormones sexuelles', 'elles déclenchent et contrôlent les changements de la puberté (testostérone chez le garçon ; œstrogènes et progestérone chez la fille).', 'corps-humain-sante', 17, 2, 'Rôle des hormones sexuelles : elles déclenchent et contrôlent les changements de la puberté (testostérone chez le garçon ; œstrogènes et progestérone chez la fille).', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-03-1', 'corps-sante-ch07', 'Caractères sexuels primaires', 'organes reproducteurs présents dès la naissance (testicules, ovaires, pénis, utérus).', 'corps-humain-sante', 17, 3, 'Caractères sexuels primaires : organes reproducteurs présents dès la naissance (testicules, ovaires, pénis, utérus).', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-04-1', 'corps-sante-ch07', 'Caractères sexuels secondaires', 'transformations visibles à la puberté (pilosité, développement des seins, mue de la voix, élargissement des épaules ou du bassin).', 'corps-humain-sante', 17, 4, 'Caractères sexuels secondaires : transformations visibles à la puberté (pilosité, développement des seins, mue de la voix, élargissement des épaules ou du bassin).', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-05-1', 'corps-sante-ch07', 'Système reproducteur masculin', 'produit les spermatozoïdes dans les testicules et la testostérone ; permet l’émission des gamètes.', 'corps-humain-sante', 17, 5, 'Système reproducteur masculin : produit les spermatozoïdes dans les testicules et la testostérone ; permet l’émission des gamètes.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-06-1', 'corps-sante-ch07', 'Système reproducteur féminin', 'produit les ovules dans les ovaires ; fonctionnement cyclique avec le cycle menstruel ; rôle de l’utérus dans une éventuelle grossesse.', 'corps-humain-sante', 17, 6, 'Système reproducteur féminin : produit les ovules dans les ovaires ; fonctionnement cyclique avec le cycle menstruel ; rôle de l’utérus dans une éventuelle grossesse.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p17-07-1', 'corps-sante-ch07', 'Fonction commune', 'permettre la reproduction sexuée par la rencontre d’un spermatozoïde et d’un ovule.', 'corps-humain-sante', 17, 7, 'Fonction commune : permettre la reproduction sexuée par la rencontre d’un spermatozoïde et d’un ovule.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-01-1', 'corps-sante-ch08', 'Gamètes', 'cellules reproductrices haploïdes -> spermatozoïde (mâle) et ovule (femelle).', 'corps-humain-sante', 20, 1, 'Gamètes : cellules reproductrices haploïdes -> spermatozoïde (mâle) et ovule (femelle).', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-02-1', 'corps-sante-ch08', 'Fécondation', 'rencontre et fusion des noyaux des deux gamètes. Elle a lieu dans une trompe de Fallope.', 'corps-humain-sante', 20, 2, 'Fécondation : rencontre et fusion des noyaux des deux gamètes. Elle a lieu dans une trompe de Fallope.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-03-1', 'corps-sante-ch08', 'Cellule-œuf (zygote)', 'cellule issue de la fécondation, contenant un patrimoine génétique unique.', 'corps-humain-sante', 20, 3, 'Cellule-œuf (zygote) : cellule issue de la fécondation, contenant un patrimoine génétique unique.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-04-1', 'corps-sante-ch08', 'Divisions cellulaires', 'le zygote se divise par mitoses successives sans augmentation de taille globale (segmentation).', 'corps-humain-sante', 20, 4, 'Divisions cellulaires : le zygote se divise par mitoses successives sans augmentation de taille globale (segmentation).', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-05-1', 'corps-sante-ch08', 'Embryogenèse précoce', 'ensemble des étapes allant de la cellule-œuf à l’embryon pluricellulaire organisé.', 'corps-humain-sante', 20, 5, 'Embryogenèse précoce : ensemble des étapes allant de la cellule-œuf à l’embryon pluricellulaire organisé.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-06-1', 'corps-sante-ch08', 'Différenciation cellulaire', 'les cellules issues des divisions se spécialisent progressivement (tissus, organes).', 'corps-humain-sante', 20, 6, 'Différenciation cellulaire : les cellules issues des divisions se spécialisent progressivement (tissus, organes).', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p20-07-1', 'corps-sante-ch08', 'Implantation', 'l’embryon s’implante dans la paroi de l’utérus (nidation).', 'corps-humain-sante', 20, 7, 'Implantation : l’embryon s’implante dans la paroi de l’utérus (nidation).', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-01-1', 'corps-sante-ch09', 'Placenta', 'organe temporaire formé au début de la grossesse, reliant le fœtus à l’organisme maternel.', 'corps-humain-sante', 22, 1, 'Placenta : organe temporaire formé au début de la grossesse, reliant le fœtus à l’organisme maternel.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-02-1', 'corps-sante-ch09', 'Fonction d’échanges', 'permet le passage du dioxygène et des nutriments de la mère vers le fœtus.', 'corps-humain-sante', 22, 2, 'Fonction d’échanges : permet le passage du dioxygène et des nutriments de la mère vers le fœtus.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-03-1', 'corps-sante-ch09', 'Élimination des déchets', 'le dioxyde de carbone et certains déchets provenant du fœtus sont éliminés vers le sang maternel.', 'corps-humain-sante', 22, 3, 'Élimination des déchets : le dioxyde de carbone et certains déchets provenant du fœtus sont éliminés vers le sang maternel.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-04-1', 'corps-sante-ch09', 'Barrière placentaire', 'les sangs maternel et fœtal ne se mélangent pas ; les échanges se font à travers des membranes fines.', 'corps-humain-sante', 22, 4, 'Barrière placentaire : les sangs maternel et fœtal ne se mélangent pas ; les échanges se font à travers des membranes fines.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-05-1', 'corps-sante-ch09', 'Rôle nutritif', 'apporte glucose, acides aminés, lipides, eau et sels minéraux nécessaires à la croissance du fœtus.', 'corps-humain-sante', 22, 5, 'Rôle nutritif : apporte glucose, acides aminés, lipides, eau et sels minéraux nécessaires à la croissance du fœtus.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-06-1', 'corps-sante-ch09', 'Rôle respiratoire', 'assure les échanges gazeux, le fœtus ne respirant pas par les poumons.', 'corps-humain-sante', 22, 6, 'Rôle respiratoire : assure les échanges gazeux, le fœtus ne respirant pas par les poumons.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p22-07-1', 'corps-sante-ch09', 'Rôle protecteur partiel', 'filtre certaines substances mais laisse passer des éléments nocifs (alcool, nicotine, certains médicaments).', 'corps-humain-sante', 22, 7, 'Rôle protecteur partiel : filtre certaines substances mais laisse passer des éléments nocifs (alcool, nicotine, certains médicaments).', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-01-1', 'corps-sante-ch10', 'Contraception', 'ensemble des méthodes visant à éviter une grossesse lors d’un rapport sexuel.', 'corps-humain-sante', 24, 1, 'Contraception : ensemble des méthodes visant à éviter une grossesse lors d’un rapport sexuel.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-02-1', 'corps-sante-ch10', 'Contraception naturelle', 'repose en grande partie sur l’observation du cycle menstruel (abstinence périodique, méthode des températures, observation de la glaire cervicale). L’efficacité est variable et dépendante de la rigueur et de la régularité des cycles.', 'corps-humain-sante', 24, 2, 'Contraception naturelle : repose en grande partie sur l’observation du cycle menstruel (abstinence périodique, méthode des températures, observation de la glaire cervicale). L’efficacité est variable et dépendante de la rigueur et de la régularité des cycles.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-03-1', 'corps-sante-ch10', 'Contraception mécanique (barrière)', 'empêche physiquement la rencontre des gamètes (préservatif masculin et féminin, diaphragme). Le préservatif protège aussi contre les IST.', 'corps-humain-sante', 24, 3, 'Contraception mécanique (barrière) : empêche physiquement la rencontre des gamètes (préservatif masculin et féminin, diaphragme). Le préservatif protège aussi contre les IST.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-04-1', 'corps-sante-ch10', 'Contraception hormonale', 'agit sur le fonctionnement du cycle ovarien (pilule, patch, implant, injection). Elle bloque l’ovulation et/ou modifie la muqueuse utérine.', 'corps-humain-sante', 24, 4, 'Contraception hormonale : agit sur le fonctionnement du cycle ovarien (pilule, patch, implant, injection). Elle bloque l’ovulation et/ou modifie la muqueuse utérine.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-05-1', 'corps-sante-ch10', 'Efficacité contraceptive', 'dépend du type de méthode et de son bon usage ; les méthodes hormonales et mécaniques sont plus fiables que les méthodes naturelles.', 'corps-humain-sante', 24, 5, 'Efficacité contraceptive : dépend du type de méthode et de son bon usage ; les méthodes hormonales et mécaniques sont plus fiables que les méthodes naturelles.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-06-1', 'corps-sante-ch10', 'Choix de la contraception', 'dépend de l’âge, de la situation personnelle, de la santé et doit être encadré médicalement pour les méthodes hormonales.', 'corps-humain-sante', 24, 6, 'Choix de la contraception : dépend de l’âge, de la situation personnelle, de la santé et doit être encadré médicalement pour les méthodes hormonales.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p24-07-1', 'corps-sante-ch10', 'Prévention des IST', 'seule la contraception mécanique par préservatif protège contre les infections sexuellement transmissibles.', 'corps-humain-sante', 24, 7, 'Prévention des IST : seule la contraception mécanique par préservatif protège contre les infections sexuellement transmissibles.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-01-1', 'corps-sante-ch11', 'Procréation médicalement assistée (PMA)', 'La PMA désigne l’ensemble des techniques médicales qui aident à la conception sans rapport sexuel fécondant.', 'corps-humain-sante', 26, 1, 'La PMA désigne l’ensemble des techniques médicales qui aident à la conception sans rapport sexuel fécondant.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-02-1', 'corps-sante-ch11', 'Indications de la PMA', 'Elle est utilisée en cas d’infertilité d’un ou des deux membres du couple ou de risque de transmission d’une maladie grave.', 'corps-humain-sante', 26, 2, 'Elle est utilisée en cas d’infertilité d’un ou des deux membres du couple ou de risque de transmission d’une maladie grave.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-03-1', 'corps-sante-ch11', 'Lieu de la fécondation en PMA', 'La fécondation peut avoir lieu dans le corps de la femme ou en laboratoire.', 'corps-humain-sante', 26, 3, 'La fécondation peut avoir lieu dans le corps de la femme ou en laboratoire.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-04-1', 'corps-sante-ch11', 'Insémination artificielle', 'L’insémination artificielle consiste à introduire des spermatozoïdes dans l’utérus au moment de l’ovulation.', 'corps-humain-sante', 26, 4, 'L’insémination artificielle consiste à introduire des spermatozoïdes dans l’utérus au moment de l’ovulation.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-05-1', 'corps-sante-ch11', 'Fécondation in vitro (FIV)', 'La fécondation in vitro (FIV) consiste à féconder un ovule par un spermatozoïde en laboratoire avant le transfert de l’embryon dans l’utérus.', 'corps-humain-sante', 26, 5, 'La fécondation in vitro (FIV) consiste à féconder un ovule par un spermatozoïde en laboratoire avant le transfert de l’embryon dans l’utérus.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p26-06-1', 'corps-sante-ch11', 'Bases biologiques de la PMA', 'La PMA repose sur la connaissance du cycle ovarien, de l’ovulation et de la fécondation.', 'corps-humain-sante', 26, 6, 'La PMA repose sur la connaissance du cycle ovarien, de l’ovulation et de la fécondation.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-01-1', 'corps-sante-ch12', 'Infection sexuellement transmissible (IST)', 'Une IST est une infection causée par un virus, une bactérie ou un parasite transmis lors de rapports sexuels.', 'corps-humain-sante', 28, 1, 'Une IST est une infection causée par un virus, une bactérie ou un parasite transmis lors de rapports sexuels.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-02-1', 'corps-sante-ch12', 'Transmission des IST', 'Les IST se transmettent lors de rapports sexuels non protégés, par contact avec des fluides sexuels ou du sang.', 'corps-humain-sante', 28, 2, 'Les IST se transmettent lors de rapports sexuels non protégés, par contact avec des fluides sexuels ou du sang.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-03-1', 'corps-sante-ch12', 'IST asymptomatiques', 'Certaines IST peuvent être asymptomatiques, ce qui favorise leur transmission.', 'corps-humain-sante', 28, 3, 'Certaines IST peuvent être asymptomatiques, ce qui favorise leur transmission.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-04-1', 'corps-sante-ch12', 'Exemples d’IST', 'Le VIH, la chlamydia, la syphilis et le papillomavirus sont des exemples d’IST.', 'corps-humain-sante', 28, 4, 'Le VIH, la chlamydia, la syphilis et le papillomavirus sont des exemples d’IST.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-05-1', 'corps-sante-ch12', 'Préservatif et IST', 'Le préservatif est le seul moyen de prévention efficace contre la majorité des IST lors des rapports sexuels.', 'corps-humain-sante', 28, 5, 'Le préservatif est le seul moyen de prévention efficace contre la majorité des IST lors des rapports sexuels.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-06-1', 'corps-sante-ch12', 'Dépistage des IST', 'Le dépistage permet de détecter une IST même en l’absence de symptômes.', 'corps-humain-sante', 28, 6, 'Le dépistage permet de détecter une IST même en l’absence de symptômes.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p28-07-1', 'corps-sante-ch12', 'Prévention des IST', 'La prévention repose sur l’information, la protection et le suivi médical.', 'corps-humain-sante', 28, 7, 'La prévention repose sur l’information, la protection et le suivi médical.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-01-1', 'corps-sante-ch13', 'Consentement', 'Le consentement est un accord volontaire donné sans contrainte ni pression.', 'corps-humain-sante', 30, 1, 'Le consentement est un accord volontaire donné sans contrainte ni pression.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-02-1', 'corps-sante-ch13', 'Caractère explicite du consentement', 'Il doit être clair, explicite et compréhensible par toutes les personnes concernées.', 'corps-humain-sante', 30, 2, 'Il doit être clair, explicite et compréhensible par toutes les personnes concernées.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-03-1', 'corps-sante-ch13', 'Réversibilité du consentement', 'Le consentement peut être retiré à tout moment.', 'corps-humain-sante', 30, 3, 'Le consentement peut être retiré à tout moment.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-04-1', 'corps-sante-ch13', 'Absence de refus et consentement', 'L’absence de refus ne signifie pas consentement.', 'corps-humain-sante', 30, 4, 'L’absence de refus ne signifie pas consentement.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-05-1', 'corps-sante-ch13', 'Respect', 'Le respect implique l’écoute des limites et des choix de l’autre.', 'corps-humain-sante', 30, 5, 'Le respect implique l’écoute des limites et des choix de l’autre.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p30-06-1', 'corps-sante-ch13', 'Consentement et intégrité de la personne', 'Le consentement s’inscrit dans le respect de l’intégrité physique et morale.', 'corps-humain-sante', 30, 6, 'Le consentement s’inscrit dans le respect de l’intégrité physique et morale.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-01-1', 'corps-sante-ch14', 'Immunité innée', 'L’immunité innée est la première ligne de défense de l’organisme ; elle agit immédiatement dès l’entrée d’un agent pathogène, sans reconnaissance spécifique.', 'corps-humain-sante', 32, 1, 'L’immunité innée est la première ligne de défense de l’organisme ; elle agit immédiatement dès l’entrée d’un agent pathogène, sans reconnaissance spécifique.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-02-1', 'corps-sante-ch14', 'Mécanismes de l’immunité innée', 'Elle repose sur des barrières naturelles (peau, muqueuses), des cellules spécialisées (phagocytes) et des réactions comme l’inflammation.', 'corps-humain-sante', 32, 2, 'Elle repose sur des barrières naturelles (peau, muqueuses), des cellules spécialisées (phagocytes) et des réactions comme l’inflammation.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-03-1', 'corps-sante-ch14', 'Réaction inflammatoire', 'La réaction inflammatoire se manifeste par rougeur, chaleur, douleur et gonflement ; elle permet de recruter des cellules immunitaires sur le lieu de l’infection.', 'corps-humain-sante', 32, 3, 'La réaction inflammatoire se manifeste par rougeur, chaleur, douleur et gonflement ; elle permet de recruter des cellules immunitaires sur le lieu de l’infection.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-04-1', 'corps-sante-ch14', 'Immunité adaptative', 'L’immunité adaptative intervient si l’immunité innée est insuffisante ; elle est spécifique d’un antigène donné.', 'corps-humain-sante', 32, 4, 'L’immunité adaptative intervient si l’immunité innée est insuffisante ; elle est spécifique d’un antigène donné.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-05-1', 'corps-sante-ch14', 'Lymphocytes et reconnaissance spécifique', 'Elle met en jeu des lymphocytes capables de reconnaître précisément un agent pathogène.', 'corps-humain-sante', 32, 5, 'Elle met en jeu des lymphocytes capables de reconnaître précisément un agent pathogène.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-06-1', 'corps-sante-ch14', 'Lymphocytes B', 'Les lymphocytes B produisent des anticorps qui se fixent sur l’antigène pour faciliter son élimination.', 'corps-humain-sante', 32, 6, 'Les lymphocytes B produisent des anticorps qui se fixent sur l’antigène pour faciliter son élimination.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-07-1', 'corps-sante-ch14', 'Lymphocytes T', 'Les lymphocytes T participent à la destruction des cellules infectées ou à la coordination de la réponse immunitaire.', 'corps-humain-sante', 32, 7, 'Les lymphocytes T participent à la destruction des cellules infectées ou à la coordination de la réponse immunitaire.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p32-08-1', 'corps-sante-ch14', 'Mémoire de l’immunité adaptative', 'L’immunité adaptative possède une mémoire immunitaire permettant une réponse plus rapide et plus efficace lors d’un second contact avec le même agent pathogène.', 'corps-humain-sante', 32, 8, 'L’immunité adaptative possède une mémoire immunitaire permettant une réponse plus rapide et plus efficace lors d’un second contact avec le même agent pathogène.', NULL, 81);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-01-1', 'corps-sante-ch15', 'Vaccination', 'La vaccination consiste à introduire un antigène inoffensif dans l’organisme.', 'corps-humain-sante', 35, 1, 'La vaccination consiste à introduire un antigène inoffensif dans l’organisme.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-02-1', 'corps-sante-ch15', 'Antigène', 'Un antigène déclenche une réponse immunitaire adaptative spécifique.', 'corps-humain-sante', 35, 2, 'Un antigène déclenche une réponse immunitaire adaptative spécifique.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-03-1', 'corps-sante-ch15', 'Lymphocytes mémoire', 'Des lymphocytes mémoire sont produits lors de cette première réponse.', 'corps-humain-sante', 35, 3, 'Des lymphocytes mémoire sont produits lors de cette première réponse.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-04-1', 'corps-sante-ch15', 'Mémoire immunitaire adaptative', 'La mémoire immunitaire adaptative permet une réponse plus rapide et plus efficace lors d’un nouveau contact avec le même agent pathogène.', 'corps-humain-sante', 35, 4, 'La mémoire immunitaire adaptative permet une réponse plus rapide et plus efficace lors d’un nouveau contact avec le même agent pathogène.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-05-1', 'corps-sante-ch15', 'Protection individuelle et collective', 'La vaccination protège l’individu et contribue à la protection collective.', 'corps-humain-sante', 35, 5, 'La vaccination protège l’individu et contribue à la protection collective.', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p35-06-1', 'corps-sante-ch15', 'Principe immunitaire de la vaccination', 'La vaccination s’appuie sur le fonctionnement normal du système immunitaire.', 'corps-humain-sante', 35, 6, 'La vaccination s’appuie sur le fonctionnement normal du système immunitaire.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-01-1', 'corps-sante-ch16', 'Hormones', 'substances chimiques produites par des glandes endocrines et libérées dans le sang', 'corps-humain-sante', 37, 1, 'Hormones : substances chimiques produites par des glandes endocrines et libérées dans le sang', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-02-1', 'corps-sante-ch16', 'Rôle des hormones', 'elles agissent à distance sur des organes cibles et régulent croissance, métabolisme, reproduction et adaptation à l’effort ou au stress.', 'corps-humain-sante', 37, 2, 'Rôle des hormones : elles agissent à distance sur des organes cibles et régulent croissance, métabolisme, reproduction et adaptation à l’effort ou au stress.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-03-1', 'corps-sante-ch16', 'Spécificité', 'chaque hormone agit sur des cellules possédant des récepteurs spécifiques.', 'corps-humain-sante', 37, 3, 'Spécificité : chaque hormone agit sur des cellules possédant des récepteurs spécifiques.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-04-1', 'corps-sante-ch16', 'Exemples d’hormones', 'insuline (régulation de la glycémie), adrénaline (réponse au stress), hormones sexuelles (puberté, reproduction).', 'corps-humain-sante', 37, 4, 'Exemples d’hormones : insuline (régulation de la glycémie), adrénaline (réponse au stress), hormones sexuelles (puberté, reproduction).', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-05-1', 'corps-sante-ch16', 'Homéostasie', 'capacité de l’organisme à maintenir des constantes internes (température, glycémie, taux d’eau).', 'corps-humain-sante', 37, 5, 'Homéostasie : capacité de l’organisme à maintenir des constantes internes (température, glycémie, taux d’eau).', NULL, 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-06-1', 'corps-sante-ch16', 'Régulation hormonale', 'repose souvent sur des mécanismes de rétrocontrôle (feedback négatif).', 'corps-humain-sante', 37, 6, 'Régulation hormonale : repose souvent sur des mécanismes de rétrocontrôle (feedback négatif).', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p37-07-1', 'corps-sante-ch16', 'Lien système nerveux / hormonal', 'le système nerveux agit rapidement ; le système hormonal agit plus lentement mais durablement.', 'corps-humain-sante', 37, 7, 'Lien système nerveux / hormonal : le système nerveux agit rapidement ; le système hormonal agit plus lentement mais durablement.', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-01-1', 'corps-sante-ch17', 'Homéostasie', 'capacité de l’organisme à maintenir des constantes internes malgré les variations du milieu extérieur.', 'corps-humain-sante', 39, 1, 'Homéostasie: capacité de l’organisme à maintenir des constantes internes malgré les variations du milieu extérieur.', NULL, 11);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-02-1', 'corps-sante-ch17', 'Glycémie', 'concentration de glucose dans le sang, normalement proche de 1 g/L.', 'corps-humain-sante', 39, 2, 'Glycémie: concentration de glucose dans le sang, normalement proche de 1 g/L.', NULL, 21);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-03-1', 'corps-sante-ch17', 'Régulation de la glycémie', 'assurée principalement par le pancréas grâce à deux hormones antagonistes.', 'corps-humain-sante', 39, 3, 'Régulation de la glycémie : assurée principalement par le pancréas grâce à deux hormones antagonistes.', NULL, 31);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-04-1', 'corps-sante-ch17', 'Insuline', 'hormone hypoglycémiante sécrétée quand la glycémie augmente ; favorise l’entrée du glucose dans les cellules et son stockage.', 'corps-humain-sante', 39, 4, 'Insuline : hormone hypoglycémiante sécrétée quand la glycémie augmente ; favorise l’entrée du glucose dans les cellules et son stockage.', NULL, 41);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-05-1', 'corps-sante-ch17', 'Glucagon', 'hormone hypoglycémiante sécrétée quand la glycémie baisse ; stimule la libération de glucose par le foie.', 'corps-humain-sante', 39, 5, 'Glucagon : hormone hypoglycémiante sécrétée quand la glycémie baisse ; stimule la libération de glucose par le foie.', 'Incohérence dans le PDF : le glucagon est qualifié d’hypoglycémiant alors que la même phrase décrit une libération de glucose. Texte source conservé ; formulation à vérifier avant mémorisation.', 51);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-06-1', 'corps-sante-ch17', 'Température corporelle', 'maintenue autour de 37 °C chez l’être humain.', 'corps-humain-sante', 39, 6, 'Température corporelle : maintenue autour de 37 °C chez l’être humain.', NULL, 61);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-07-1', 'corps-sante-ch17', 'Régulation thermique', 'le cerveau (hypothalamus) coordonne les réponses (transpiration, frissons, dilatation ou contraction des vaisseaux).', 'corps-humain-sante', 39, 7, 'Régulation thermique : le cerveau (hypothalamus) coordonne les réponses (transpiration, frissons, dilatation ou contraction des vaisseaux).', NULL, 71);
INSERT INTO definitions (id, chapter_id, concept, definition, source_id, source_page, source_item, source_excerpt, review_note, position) VALUES ('corps-sante-p39-08-1', 'corps-sante-ch17', 'Rétrocontrôle', 'les variations de glycémie ou de température déclenchent des réponses qui tendent à rétablir la valeur de référence.', 'corps-humain-sante', 39, 8, 'Rétrocontrôle: les variations de glycémie ou de température déclenchent des réponses qui tendent à rétablir la valeur de référence.', NULL, 81);
